import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    keys = []
    for item in data:
        if isinstance(item, str):
            d = ast.literal_eval(item)
        else:
            d = item
        keys.extend(d.keys())
    return Counter(keys)
